import React from 'react';
import { Kit } from './index';

const previews = {
  componentName: 'Kit',
  importPath: 'components/Kit',
  previews: [
    { name: '3D rig', description: "Scenery kit showcase: trees, bench, bin, lamp, fountain, statue and flower bed together.", render: () => <Kit /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';

// Shared scenery builders — modelled from RCT2 scenery sprites. Static builders
// return a THREE.Group; animated ones return { group, update }.
export type T = typeof THREE;

export function tree(t: T, opts: { shape?: 'round' | 'pine' | 'palm' | 'willow'; scale?: number } = {}) {
  const shape = opts.shape ?? 'round';
  const g = new t.Group();
  const BARK = 0x5a3d22;
  if (shape === 'pine') {
    g.add(cyl(t, 0.1, 0.16, 1.0, BARK, [0, 0.5, 0], { tex: 'wood', repeat: [2, 3], rough: 1 }));
    for (let i = 0; i < 4; i++)
      g.add(cyl(t, 0.02, 0.55 - i * 0.12, 0.5, 0x2f6a34, [0, 0.95 + i * 0.42, 0], { tex: 'leaf', repeat: [3, 2], flat: true, rough: 1, seg: 8 }));
  } else if (shape === 'palm') {
    for (let s = 0; s < 6; s++) g.add(cyl(t, 0.08, 0.1, 0.28, BARK, [0, 0.15 + s * 0.26, 0], { tex: 'wood', repeat: [1, 1], rough: 1, rotZ: 0.05 * (s % 2 ? 1 : -1) }));
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * Math.PI * 2;
      const frond = box(t, [0.9, 0.04, 0.22], 0x4f9a3a, [Math.cos(a) * 0.45, 1.75, Math.sin(a) * 0.45], { tex: 'leaf', repeat: [3, 1], flat: true, rough: 1, rotY: -a, rotZ: -0.35 });
      g.add(frond);
    }
    g.add(ball(t, 0.12, 0x7a5a2a, [0, 1.7, 0], { rough: 0.8 }));
  } else if (shape === 'willow') {
    g.add(cyl(t, 0.12, 0.18, 1.0, BARK, [0, 0.5, 0], { tex: 'wood', repeat: [2, 3], rough: 1 }));
    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * Math.PI * 2;
      g.add(cyl(t, 0.04, 0.02, 0.9, 0x7a9a3a, [Math.cos(a) * 0.6, 1.15, Math.sin(a) * 0.6], { tex: 'leaf', repeat: [1, 3], flat: true, rough: 1, seg: 6 }));
    }
    g.add(ball(t, 0.6, 0x86a84a, [0, 1.5, 0], { tex: 'leaf', repeat: [3, 3], flat: true, rough: 1 }));
  } else {
    const greens = [0x6f8f3a, 0x5c7d2e, 0x86a84a, 0x7c9a40];
    g.add(cyl(t, 0.14, 0.2, 1.1, BARK, [0, 0.55, 0], { tex: 'wood', repeat: [3, 3], rough: 1 }));
    ([[0, 1.55, 0, 0.74], [-0.5, 1.36, 0.18, 0.5], [0.5, 1.42, -0.12, 0.55], [0.12, 1.9, 0, 0.5], [-0.2, 1.55, -0.45, 0.45], [0.35, 1.6, 0.4, 0.46]] as number[][]).forEach(
      (b, i) => g.add(ball(t, b[3], greens[i % 4], [b[0], b[1], b[2]], { tex: 'leaf', repeat: [3, 3], flat: true, rough: 1 })),
    );
  }
  if (opts.scale) g.scale.setScalar(opts.scale);
  return g;
}

export function bench(t: T) {
  const g = new t.Group();
  const W = 0x8a5a2a;
  for (let i = 0; i < 3; i++) g.add(box(t, [1.0, 0.04, 0.12], W, [0, 0.4, -0.16 + i * 0.16], { tex: 'wood', repeat: [4, 1], rough: 0.8 }));
  for (let i = 0; i < 3; i++) g.add(box(t, [1.0, 0.12, 0.04], W, [0, 0.55 + i * 0.13, -0.24], { tex: 'wood', repeat: [4, 1], rough: 0.8 }));
  [-0.42, 0.42].forEach((x) => {
    g.add(box(t, [0.06, 0.42, 0.5], 0x2b2b30, [x, 0.2, -0.05], { tex: 'metal', metal: 0.6, rough: 0.5 }));
    g.add(box(t, [0.06, 0.4, 0.06], 0x2b2b30, [x, 0.6, -0.24], { tex: 'metal', metal: 0.6, rough: 0.5 }));
  });
  return g;
}

export function bin(t: T) {
  const g = new t.Group();
  g.add(cyl(t, 0.16, 0.14, 0.5, 0x2f6a34, [0, 0.28, 0], { tex: 'metal', metal: 0.4, rough: 0.6, seg: 16 }));
  g.add(cyl(t, 0.18, 0.18, 0.05, 0x244f27, [0, 0.55, 0], { tex: 'metal', metal: 0.4, rough: 0.6, seg: 16 }));
  g.add(cyl(t, 0.03, 0.03, 0.5, 0x2b2b30, [0, 0.25, 0], { metal: 0.6, rough: 0.5, seg: 8 }));
  return g;
}

export function hedge(t: T, len = 2) {
  const g = new t.Group();
  g.add(box(t, [len, 0.7, 0.5], 0x3c6b2e, [0, 0.35, 0], { tex: 'leaf', repeat: [Math.round(len * 3), 3], flat: true, rough: 1, bump: 0.05 }));
  return g;
}

export function flowerBed(t: T) {
  const g = new t.Group();
  g.add(box(t, [1.2, 0.2, 1.2], 0x6a4a2c, [0, 0.1, 0], { tex: 'wood', repeat: [4, 4], rough: 1 }));
  g.add(box(t, [1.1, 0.08, 1.1], 0x3c6b2e, [0, 0.22, 0], { tex: 'leaf', repeat: [4, 4], flat: true, rough: 1 }));
  const cols = [0xe23a3a, 0xf0d000, 0xe060a0, 0xffffff, 0x7a4de0];
  for (let i = 0; i < 24; i++) {
    const x = (Math.random() - 0.5) * 1.0;
    const z = (Math.random() - 0.5) * 1.0;
    g.add(cyl(t, 0.005, 0.005, 0.14, 0x2f6a34, [x, 0.32, z], { seg: 5 }));
    g.add(ball(t, 0.05, cols[i % cols.length], [x, 0.4, z], { flat: true, rough: 0.7 }));
  }
  return g;
}

export function rock(t: T, scale = 1) {
  const g = new t.Group();
  const grey = [0x8a8880, 0x76746c, 0x9a988f];
  for (let i = 0; i < 5; i++) {
    const b = ball(t, 0.25 + Math.random() * 0.25, grey[i % 3], [(Math.random() - 0.5) * 0.5, 0.2 + Math.random() * 0.2, (Math.random() - 0.5) * 0.5], {
      tex: 'concrete',
      repeat: [2, 2],
      flat: true,
      rough: 1,
    });
    b.scale.set(1, 0.7, 1);
    g.add(b);
  }
  g.scale.setScalar(scale);
  return g;
}

export function statue(t: T, kind: 'obelisk' | 'knight' | 'urn' | 'giraffe' = 'knight') {
  const g = new t.Group();
  const STONE = 0xb9b09a;
  g.add(box(t, [0.9, 0.3, 0.9], STONE, [0, 0.15, 0], { tex: 'concrete', repeat: [3, 1], rough: 0.9 }));
  g.add(box(t, [0.6, 0.4, 0.6], STONE, [0, 0.5, 0], { tex: 'concrete', repeat: [2, 1], rough: 0.9 }));
  if (kind === 'obelisk') {
    g.add(box(t, [0.28, 1.6, 0.28], STONE, [0, 1.5, 0], { tex: 'concrete', repeat: [1, 4], rough: 0.9 }));
    g.add(cyl(t, 0, 0.22, 0.3, 0xe8d070, [0, 2.45, 0], { metal: 0.6, rough: 0.3, seg: 4 }));
  } else if (kind === 'urn') {
    g.add(cyl(t, 0.28, 0.16, 0.5, STONE, [0, 0.95, 0], { tex: 'concrete', repeat: [2, 1], rough: 0.9, seg: 20 }));
    g.add(cyl(t, 0.34, 0.28, 0.14, STONE, [0, 1.25, 0], { tex: 'concrete', rough: 0.9, seg: 20 }));
    g.add(ball(t, 0.28, 0x3c6b2e, [0, 1.45, 0], { tex: 'leaf', repeat: [3, 3], flat: true }));
  } else if (kind === 'giraffe') {
    for (let i = 0; i < 4; i++) g.add(box(t, [0.3, 0.9, 0.18], 0xd0d0c4, [(i - 1.5) * 0.16, 1.1 + (i % 2) * 0.1, 0], { tex: 'leaf', repeat: [1, 3], flat: true, rough: 1 }));
  } else {
    // knight-ish figure
    g.add(cyl(t, 0.16, 0.2, 0.6, STONE, [0, 1.0, 0], { tex: 'concrete', rough: 0.9, seg: 16 })); // body
    g.add(ball(t, 0.16, STONE, [0, 1.4, 0], { rough: 0.9 })); // head
    g.add(box(t, [0.08, 0.8, 0.08], STONE, [0.22, 1.1, 0], { rough: 0.9, rotZ: 0.1 })); // spear
    g.add(box(t, [0.32, 0.32, 0.03], STONE, [-0.2, 1.0, 0], { tex: 'concrete', rough: 0.9 })); // shield
  }
  return g;
}

export function foodStall(t: T) {
  const g = new t.Group();
  g.add(box(t, [1.3, 0.7, 0.8], 0xf0e6d0, [0, 0.35, 0], { tex: 'wood', repeat: [4, 2], rough: 0.7 }));
  g.add(box(t, [1.3, 0.1, 0.9], 0x8a2a2a, [0, 0.72, 0], { tex: 'fabric', repeat: [6, 1], rough: 0.7 }));
  // striped awning
  for (let i = 0; i < 6; i++) g.add(box(t, [0.2, 0.04, 0.5], i % 2 ? 0xe0e0e0 : 0xd83a3a, [-0.55 + i * 0.22, 0.86, 0.35], { rotX: -0.5, rough: 0.6 }));
  g.add(box(t, [1.2, 0.06, 0.3], 0xc9a24a, [0, 0.62, 0.4], { tex: 'wood', repeat: [4, 1], rough: 0.7 })); // counter
  return g;
}

export function fence(t: T, len = 2) {
  const g = new t.Group();
  for (let x = -len / 2; x <= len / 2; x += 0.5) g.add(cyl(t, 0.04, 0.04, 0.7, 0x8a5a2a, [x, 0.35, 0], { tex: 'wood', repeat: [1, 2], rough: 0.8, seg: 8 }));
  [0.2, 0.5].forEach((y) => g.add(box(t, [len, 0.06, 0.05], 0x8a5a2a, [0, y, 0], { tex: 'wood', repeat: [Math.round(len * 3), 1], rough: 0.8 })));
  return g;
}

export function lamp(t: T) {
  const g = new t.Group();
  const glass = new t.MeshStandardMaterial({ color: 0xfff2c0, emissive: 0xffcc55, emissiveIntensity: 1, roughness: 0.4 });
  g.add(cyl(t, 0.14, 0.18, 0.16, 0x2b2b30, [0, 0.08, 0], { tex: 'metal', metal: 0.5, rough: 0.5, seg: 12 }));
  g.add(cyl(t, 0.05, 0.06, 1.5, 0x2b2b30, [0, 0.83, 0], { tex: 'metal', metal: 0.6, rough: 0.4, seg: 12 }));
  const lantern = new t.Mesh(new t.BoxGeometry(0.24, 0.3, 0.24), glass);
  lantern.position.set(0, 1.7, 0);
  g.add(lantern);
  g.add(box(t, [0.3, 0.06, 0.3], 0x2b2b30, [0, 1.88, 0], { tex: 'metal', metal: 0.6, rough: 0.4 }));
  return { group: g, update: (time: number) => (glass.emissiveIntensity = 0.8 + Math.sin(time * 8) * 0.15 + Math.sin(time * 23) * 0.05) };
}

export function fountain(t: T) {
  const g = new t.Group();
  const STONE = 0xc3b7a0;
  g.add(cyl(t, 1.1, 1.2, 0.4, STONE, [0, 0.2, 0], { tex: 'concrete', repeat: [10, 1], rough: 0.9, seg: 28 }));
  g.add(cyl(t, 1.0, 1.0, 0.08, 0x2a6fb0, [0, 0.42, 0], { emissive: 0x134a78, rough: 0.2, metal: 0.3, seg: 28 })); // pool
  g.add(cyl(t, 0.18, 0.24, 0.9, STONE, [0, 0.85, 0], { tex: 'concrete', repeat: [3, 2], rough: 0.9, seg: 20 })); // pedestal
  g.add(cyl(t, 0.5, 0.4, 0.12, STONE, [0, 1.2, 0], { tex: 'concrete', rough: 0.9, seg: 20 })); // upper bowl
  const jets: THREE.Mesh[] = [];
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const jet = new t.Mesh(new t.CylinderGeometry(0.02, 0.04, 0.5, 6), new t.MeshStandardMaterial({ color: 0xafe0f5, transparent: true, opacity: 0.7, roughness: 0.2 }));
    jet.position.set(Math.cos(a) * 0.3, 1.5, Math.sin(a) * 0.3);
    g.add(jet);
    jets.push(jet);
  }
  return {
    group: g,
    update: (time: number) => jets.forEach((j, i) => (j.scale.y = 0.6 + Math.abs(Math.sin(time * 4 + i)) * 0.9)),
  };
}

// Showcase: a row of the scenery builders together (trees, bench, bin, lamp,
// fountain, statue, flower bed) so the Kit can be previewed at a glance.
export function Kit() {
  return (
    <Stage
      distance={8}
      targetY={0.6}
      build={(t, g) => {
        const place = (obj: THREE.Object3D, x: number, z: number) => {
          obj.position.set(x, 0, z);
          g.add(obj);
        };
        place(tree(t, { shape: 'pine' }), -3, -0.5);
        place(tree(t, { shape: 'palm' }), -1.6, 0.6);
        place(bench(t), -0.2, -0.6);
        place(bin(t), 0.7, -0.6);
        place(statue(t, 'obelisk'), 2.4, -0.4);
        place(flowerBed(t), 1.2, 0.7);
        const l = lamp(t);
        place(l.group, -2.4, 0.9);
        const f = fountain(t);
        place(f.group, 0.6, 0.9);
        return (time) => {
          l.update(time);
          f.update(time);
        };
      }}
    />
  );
}

import React from 'react';
import { WaterTile } from './index';

const previews = {
  componentName: 'WaterTile',
  importPath: 'components/WaterTile',
  previews: [
    { name: '3D rig', description: "Animated water surface with a custom GLSL wave + Fresnel + sparkle shader.", render: () => <WaterTile /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box } from '../Stage';

// Animated water surface via a custom GLSL ShaderMaterial: summed sine waves
// displace the surface, with a depth colour gradient, view-dependent Fresnel
// rim, a moving sun specular highlight and glinting sparkles. Exported so the
// TerrainMap can flood its low ground with the same shader.
export function buildWater(t: typeof THREE, size = 4, seg = 96) {
  const geo = new t.PlaneGeometry(size, size, seg, seg);
  const mat = new t.ShaderMaterial({
    transparent: true,
    uniforms: {
      uTime: { value: 0 },
      uShallow: { value: new t.Color(0x6fd0e8) },
      uDeep: { value: new t.Color(0x123f78) },
      uSun: { value: new t.Vector3(6, 11, 5).normalize() },
    },
    vertexShader: `
      uniform float uTime;
      varying float vH;
      varying vec3 vWorld;
      void main() {
        vec3 p = position;
        float w = sin(p.x * 1.5 + uTime * 1.2) * 0.06
                + sin(p.y * 2.1 + uTime * 1.6) * 0.045
                + sin((p.x + p.y) * 0.9 - uTime * 1.3) * 0.05;
        p.z += w;
        vH = w;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      precision highp float;
      uniform float uTime;
      uniform vec3 uShallow;
      uniform vec3 uDeep;
      uniform vec3 uSun;
      varying float vH;
      varying vec3 vWorld;
      void main() {
        vec3 n = normalize(cross(dFdx(vWorld), dFdy(vWorld)));
        vec3 v = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - max(dot(n, v), 0.0), 3.0);
        vec3 base = mix(uDeep, uShallow, clamp(vH * 4.0 + 0.5, 0.0, 1.0));
        vec3 l = normalize(uSun);
        vec3 h = normalize(l + v);
        float spec = pow(max(dot(n, h), 0.0), 60.0);
        float diff = max(dot(n, l), 0.0) * 0.5 + 0.5;
        vec3 col = base * diff + vec3(1.0) * spec * 0.8 + fres * vec3(0.6, 0.8, 1.0) * 0.6;
        float sp = sin(vWorld.x * 40.0 + uTime * 8.0) * sin(vWorld.z * 40.0 - uTime * 6.0);
        col += smoothstep(0.985, 1.0, sp) * 0.5;
        gl_FragColor = vec4(col, 0.87);
      }
    `,
  });
  const mesh = new t.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  return { mesh, update: (time: number) => (mat.uniforms.uTime.value = time) };
}

export function WaterTile() {
  return (
    <Stage
      distance={5}
      targetY={0.1}
      background="#bfe6f2"
      build={(t, g) => {
        // sandy basin so the water reads as a pool
        g.add(box(t, [4.2, 0.4, 4.2], 0xd9c48f, [0, -0.2, 0], { tex: 'sand', repeat: [4, 4], rough: 1 }));
        const water = buildWater(t, 4);
        water.mesh.position.y = 0.12;
        g.add(water.mesh);
        return (time) => water.update(time);
      }}
    />
  );
}

import React from 'react';
import { GrassTile } from './index';

const previews = {
  componentName: 'GrassTile',
  importPath: 'components/GrassTile',
  previews: [
    { name: '3D rig', description: "A grass land tile (textured earth slab with tufts) from the RCT2 terrain surface.", render: () => <GrassTile /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, ball } from '../Stage';

// A grass land tile modelled from the RCT2 terrain surface: a textured earth
// slab topped with grass, plus a few tufts and a pebble for detail.
export function GrassTile() {
  return (
    <Stage
      distance={4.2}
      targetY={0.2}
      build={(t, g) => {
        g.add(box(t, [2, 0.28, 2], 0x6f9e54, [0, 0.14, 0], { tex: 'grass', repeat: [3, 3], rough: 1, bump: 0.04 }));
        g.add(box(t, [2.02, 0.16, 2.02], 0x6a4a2c, [0, -0.02, 0], { tex: 'wood', repeat: [4, 1], rough: 1 })); // soil rim
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          g.add(box(t, [0.05, 0.14, 0.05], 0x5f8f3a, [Math.cos(a) * 0.7, 0.34, Math.sin(a) * 0.7], { rotZ: 0.2, rough: 0.9 }));
        }
        g.add(ball(t, 0.09, 0x9a9a92, [0.3, 0.32, -0.2], { tex: 'concrete', repeat: [2, 2], flat: true }));
      }}
    />
  );
}

import React from 'react';
import { SandTile } from './index';

const previews = {
  componentName: 'SandTile',
  importPath: 'components/SandTile',
  previews: [
    { name: '3D rig', description: "A sand land tile with dune ripples from the RCT2 desert surface.", render: () => <SandTile /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, ball } from '../Stage';

// A sand land tile modelled from the RCT2 desert surface: a textured sand slab
// with dune ripples and a couple of stones.
export function SandTile() {
  return (
    <Stage
      distance={4.2}
      targetY={0.2}
      build={(t, g) => {
        g.add(box(t, [2, 0.28, 2], 0xd9c48f, [0, 0.14, 0], { tex: 'sand', repeat: [3, 3], rough: 1, bump: 0.05 }));
        g.add(box(t, [2.02, 0.16, 2.02], 0xb59b63, [0, -0.02, 0], { tex: 'sand', repeat: [4, 1], rough: 1 }));
        // gentle dune ridges
        for (let i = -1; i <= 1; i++)
          g.add(box(t, [1.6, 0.06, 0.18], 0xcbb578, [0, 0.3, i * 0.5], { tex: 'sand', repeat: [3, 1], rough: 1, rotX: 0.05 }));
        g.add(ball(t, 0.1, 0x8f8677, [-0.4, 0.32, 0.3], { tex: 'concrete', repeat: [2, 2], flat: true }));
        g.add(ball(t, 0.07, 0x9a9182, [0.45, 0.31, -0.35], { tex: 'concrete', repeat: [2, 2], flat: true }));
      }}
    />
  );
}

import React from 'react';
import { TerrainMap } from './index';

const previews = {
  componentName: 'TerrainMap',
  importPath: 'components/TerrainMap',
  previews: [
    { name: '3D rig', description: "A generated RCT2-style landscape: stepped grass/sand tiles flooded by the water shader.", render: () => <TerrainMap /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box } from '../Stage';
import { buildWater } from '../WaterTile';

// A generated RCT2-style landscape: a grid of stepped land tiles (discrete
// heights like the game's terrain tool) textured grass on high ground and sand
// at the shoreline, flooded by the animated water shader at sea level. The
// heightfield is deterministic (summed sines) so it renders the same each time.
export function TerrainMap() {
  return (
    <Stage
      distance={11}
      targetY={0.4}
      background="#bfe6f2"
      build={(t, g) => {
        const N = 14;
        const cs = 0.62;
        const sea = 0.5;
        const height = (i: number, j: number) => {
          let h =
            0.55 +
            0.42 * Math.sin(i * 0.55) * Math.cos(j * 0.48) +
            0.28 * Math.sin((i + j) * 0.38) +
            0.18 * Math.cos(i * 0.9 - j * 0.7);
          h = Math.max(0.12, h);
          return Math.round(h / 0.22) * 0.22; // discrete land steps
        };
        for (let i = 0; i < N; i++) {
          for (let j = 0; j < N; j++) {
            const x = (i - N / 2) * cs;
            const z = (j - N / 2) * cs;
            const h = height(i, j);
            const sand = h <= sea + 0.16;
            g.add(
              box(t, [cs * 0.98, h, cs * 0.98], sand ? 0xd9c48f : 0x6f9e54, [x, h / 2, z], {
                tex: sand ? 'sand' : 'grass',
                repeat: [1, 1],
                rough: 1,
                bump: 0.03,
              }),
            );
          }
        }
        // sea-level water sheet across the whole map
        const water = buildWater(t, N * cs + 0.4, 120);
        water.mesh.position.y = sea;
        g.add(water.mesh);
        return (time) => water.update(time);
      }}
    />
